import{_ as e,o as d,c as a,a3 as o}from"./chunks/framework.CpLciM8b.js";const u=JSON.parse('{"title":"OpenTelemetry Test Conventions","description":"","frontmatter":{},"headers":[],"relativePath":"concepts/otel-conventions.md","filePath":"concepts/otel-conventions.md","lastUpdated":1785494959000}'),r={name:"concepts/otel-conventions.md"};function c(s,t,n,i,l,p){return d(),a("div",null,[...t[0]||(t[0]=[o(`<h1 id="opentelemetry-test-conventions" tabindex="-1">OpenTelemetry Test Conventions <a class="header-anchor" href="#opentelemetry-test-conventions" aria-label="Permalink to &quot;OpenTelemetry Test Conventions&quot;">​</a></h1><p>The canonical span and attribute model every reporter emits to. The machine-readable source of truth is <a href="https://github.com/AKogut/flakemetry/blob/main/packages/contracts/src/otel.ts" target="_blank" rel="noreferrer"><code>packages/contracts/src/otel.ts</code></a> (re-exported from <code>@flakemetry/sdk</code>); this document is the human-readable spec. Product rationale lives in <a href="https://github.com/AKogut/flakemetry/blob/main/docs/adr/0002-otel-native-ingestion.md" target="_blank" rel="noreferrer">ADR-0002</a> and the <a href="https://github.com/AKogut/flakemetry/wiki/OTel-Test-Conventions" target="_blank" rel="noreferrer">wiki</a>.</p><p>Conventions version: <code>0.1.0</code>.</p><h2 id="span-hierarchy" tabindex="-1">Span hierarchy <a class="header-anchor" href="#span-hierarchy" aria-label="Permalink to &quot;Span hierarchy&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>test.run                 root span — one CI job / suite invocation</span></span>
<span class="line"><span> └─ test.case            one execution of one test (retries are separate cases)</span></span>
<span class="line"><span>     └─ test.step        a step / hook (added in M2)</span></span></code></pre></div><p>M1 emits <code>test.run</code> + <code>test.case</code>. <code>test.step</code> and network/browser child spans arrive in M2.</p><h2 id="resource-run-attributes" tabindex="-1">Resource / run attributes <a class="header-anchor" href="#resource-run-attributes" aria-label="Permalink to &quot;Resource / run attributes&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Key</th><th>Example</th><th>Meaning</th></tr></thead><tbody><tr><td><code>service.name</code></td><td><code>flakemetry-reporter</code></td><td>standard OTel service identity</td></tr><tr><td><code>flakemetry.project</code></td><td><code>acme/web</code></td><td>project the results belong to</td></tr><tr><td><code>ci.provider</code></td><td><code>github_actions</code></td><td>CI provider</td></tr><tr><td><code>ci.run_id</code></td><td><code>9000001</code></td><td>provider run id — correlates parallel shards into one logical run</td></tr><tr><td><code>test.shard.index</code></td><td><code>2</code></td><td>shard number (1-based), when the run is sharded across parallel jobs</td></tr><tr><td><code>test.shard.total</code></td><td><code>4</code></td><td>total shard count, when sharded</td></tr><tr><td><code>vcs.commit_sha</code></td><td><code>a1b2c3d</code></td><td>commit under test — enables the same-sha flake signal</td></tr><tr><td><code>vcs.branch</code></td><td><code>main</code></td><td>branch</td></tr><tr><td><code>vcs.pr_number</code></td><td><code>42</code></td><td>pull request, when applicable</td></tr><tr><td><code>flakemetry.trigger</code></td><td><code>push</code></td><td>run trigger (<code>push</code>/<code>pull_request</code>/<code>schedule</code>/<code>manual</code>/<code>other</code>)</td></tr><tr><td><code>flakemetry.idempotency_key</code></td><td><code>gh-9000001-1</code></td><td>one per ingested run; makes re-delivery safe (falls back to the run span trace id). A sharded run sends one key per shard — the reporter appends <code>-shard&lt;index&gt;</code> so parallel shards don&#39;t overwrite each other</td></tr><tr><td><code>flakemetry.contract_version</code></td><td><code>0.1.0</code></td><td>conventions/contract version stamp</td></tr></tbody></table><h2 id="case-span-attributes" tabindex="-1">Case span attributes <a class="header-anchor" href="#case-span-attributes" aria-label="Permalink to &quot;Case span attributes&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Key</th><th>Example</th><th>Meaning</th></tr></thead><tbody><tr><td><code>test.identity.fingerprint</code></td><td><code>sha256:…</code></td><td>stable identity (L1), computed by the reporter</td></tr><tr><td><code>test.suite</code></td><td><code>auth</code></td><td>grouping</td></tr><tr><td><code>test.title</code></td><td><code>logs in</code></td><td>display name</td></tr><tr><td><code>test.file_path</code></td><td><code>e2e/auth/login.spec.ts</code></td><td>source location</td></tr><tr><td><code>test.params_hash</code></td><td><code>9f2c…</code></td><td>parameterized bucket, omitted when absent</td></tr><tr><td><code>test.status</code></td><td><code>pass | fail | skip | flaky</code></td><td>verdict</td></tr><tr><td><code>test.attempt</code></td><td><code>2</code></td><td>retry index (1-based)</td></tr><tr><td><code>test.retry_of</code></td><td><code>0</code></td><td>index of the attempt this one retries, when applicable</td></tr><tr><td><code>test.duration_ms</code></td><td><code>1834</code></td><td>wall-clock duration</td></tr><tr><td><code>test.artifacts</code></td><td><code>[{&quot;name&quot;:&quot;trace&quot;,…}]</code></td><td>JSON array of artifact refs (screenshot/video/trace), workspace-relative paths</td></tr></tbody></table><h2 id="status-mapping" tabindex="-1">Status mapping <a class="header-anchor" href="#status-mapping" aria-label="Permalink to &quot;Status mapping&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Test status</th><th>OTel span status</th></tr></thead><tbody><tr><td><code>pass</code>, <code>flaky</code></td><td><code>OK</code></td></tr><tr><td><code>fail</code></td><td><code>ERROR</code> (+ exception event carrying type / message / stack)</td></tr><tr><td><code>skip</code></td><td><code>UNSET</code></td></tr></tbody></table><h2 id="fingerprint-l1" tabindex="-1">Fingerprint (L1) <a class="header-anchor" href="#fingerprint-l1" aria-label="Permalink to &quot;Fingerprint (L1)&quot;">​</a></h2><p><code>sha256(normalized_file_path + &#39; &#39; + suite + &#39; &#39; + title + &#39; &#39; + params_hash)</code> where the path is workspace-relative, POSIX-separated and lowercased. This is the exact-match layer (L1). The server-side identity engine stitches history on top of it: <strong>L2</strong> re-links a test whose file moved (same suite + title + params), and <strong>L3</strong> re-links a renamed test when — within the same file, suite and params bucket — exactly one prior test has a sufficiently similar title (token-Jaccard ≥ 0.5); ambiguous matches are left as new to avoid collapsing distinct tests. Parameterized cases stay distinct by <code>params_hash</code>.</p><h2 id="otlp-→-contracts-mapping" tabindex="-1">OTLP → contracts mapping <a class="header-anchor" href="#otlp-→-contracts-mapping" aria-label="Permalink to &quot;OTLP → contracts mapping&quot;">​</a></h2><p>Reporters export real OTLP spans via <code>@opentelemetry/exporter-trace-otlp-http</code> to <code>POST /v1/traces</code> (OTLP/HTTP JSON). The API normalizes the span tree into a contract-valid <code>ingestRunBatch</code> (<code>@flakemetry/contracts</code>) with <code>otlpToIngestBatch</code> before enqueueing, so downstream stages stay transport-agnostic. Field mapping:</p><table tabindex="0"><thead><tr><th>Batch field</th><th>Source</th></tr></thead><tbody><tr><td><code>resource.*</code></td><td>run/resource attributes above (read from the OTLP Resource, falling back to <code>test.run</code> span attributes)</td></tr><tr><td><code>executions[].{filePath,suite,title,status,attempt,durationMs}</code></td><td>case span attributes</td></tr><tr><td><code>executions[].retryOfIndex</code></td><td><code>test.retry_of</code> when present, otherwise reconstructed from attempt ordering per fingerprint</td></tr><tr><td><code>executions[].error</code></td><td>the case span <code>exception</code> event (<code>exception.type</code> / <code>exception.message</code> / <code>exception.stacktrace</code>)</td></tr><tr><td><code>run.status</code></td><td><code>test.run</code> span status (<code>ERROR</code> → <code>failed</code>), or any failing case</td></tr><tr><td><code>idempotencyKey</code></td><td><code>flakemetry.idempotency_key</code>, else the run span trace id</td></tr></tbody></table>`,17)])])}const m=e(r,[["render",c]]);export{u as __pageData,m as default};
